import { Spine } from '@esotericsoftware/spine-pixi-v8';
import { TextStyleOptions, Text } from 'pixi.js';
import SpineExtended from '../spine/spine-extended';
/**
 * @deprecated SpineSlotText has been deprecated and will be fully removed in a future release.
 *
 * This can easily be done with `spine.addSlotObject(text)` in pixi8.
 *
 * If needed remove any previous attachment with `slot.setAttachment(null)`.
 */
export default class SpineSlotText<T extends Text> {
    currentText: T;
    /**
     * Generates new text that will be rendered as a texture and placed on a slot on a spine asset
     * @param parentSpine The spine asset that the slot is attacted to.
     * @param slot The slot that will be given the new texture.
     * @param text The text that is to be displayed on the texture.
     * @param style style for the text TextStyleOptions.
     */
    newText(parentSpine: Spine | SpineExtended, slot: string, text: string, style: TextStyleOptions): void;
    /**
     * Alphas the text to a desired alpha over a specific duration
     * @param alphaAmount Value of alpha.
     * @param duration (optional) Duration taken to change to desired alpha in seconds (default 0.5s)
     */
    alphaText(alphaAmount: number, duration?: number): void;
    /**
     * Updates the text
     * @param text (optional) new text (defaults to blank)
     */
    updateText(text?: string): void;
}
